const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const fs = require('fs');
(async()=>{
 const browser=await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox']});
 const context=await browser.newContext({viewport:{width:390,height:844},hasTouch:true,isMobile:true});
 const page=await context.newPage();
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 const source=fs.readFileSync('game.js','utf8').replace(/\}\)\(\);\s*$/,'window.__testState=()=>({x:player.x,y:player.y,angle:player.angle,pitch:player.pitch,aiming,ammo,weapon,keys:{...keys}});})();');
 await page.route('**/game.js',route=>route.fulfill({status:200,contentType:'application/javascript',body:source}));
 await page.goto('http://127.0.0.1:8765');
 await page.locator('#deployBtn').click();
 await page.waitForTimeout(100);
 console.log('mobile controls visible:',await page.locator('#mobileControls').isVisible());
 const before=await page.evaluate(()=>window.__testState());
 const cdp=await context.newCDPSession(page);await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:2});
 const box=await page.locator('.movePad [data-key="w"]').boundingBox();
 await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:box.x+box.width/2,y:box.y+box.height/2,id:1}]});
 await page.waitForTimeout(300);
 await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
 const afterMove=await page.evaluate(()=>window.__testState());
 const canvas=await page.locator('#scene').boundingBox();let x=canvas.width*.5,y=canvas.height*.4;
 await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x,y,id:2}]});
 await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:x+60,y:y+30,id:2}]});
 await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
 const afterLook=await page.evaluate(()=>window.__testState());
 console.log(JSON.stringify({before,afterMove,afterLook,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
